Method.Implementation:
	// Column names

 	Set result=##class(%ResultSet).%New("%DynamicQuery:SQL")
	Do result.Prepare("SELECT top 1 * FROM " _ tableName)
	Do result.Execute()
	set colNames=""

	for j = 1:1:result.%ResultColumnCount {
		Do propertyList.Insert(result.GetColumnName(j)) 		
	}
	set ^webService(tableName _ " # columns ") = propertyList.Count()
	Do result.Close()


	While rs.%Next() {

    	if ( rs.%SQLCODE = 0)
    	{

    		set ^webService(tableName _ " rs: ") = rs.%SQLCODE _ " at " _ $ZDATETIME($HOROLOG,3, 1) _ ", ID: " _ (rs.%Get("ID"))
    		set innerArr = []
    		set val = ""

    		for ind=1:1:propertyList.Count()
    		{
    		    set column = propertyList.GetAt(ind)

    		    set val = rs.%Get(column)
    		    set ^webService(tableName _ " Data") = 	ind _": " _	column _", " _ val
    		    if (column = "InterchangeDateTime")
    		    {
	    		    set dtTm = rs.%Get(column)
	    		    if ($LENGTH(dtTm) >= 10)
	    		    {

						 set val =  $E(dtTm, 1, 2) _ "-"_  $E(dtTm, 3, 4) _ "-"_  $E(dtTm, 5, 6) _ " "_  $E(dtTm, 7, 8) _ ":"_  $E(dtTm, 9, 10)
						 if ($E(dtTm, 1, 2) < 70) // Decide 19 or 20?
						 {
						 	set val = "20" _ val
						 }
						 else
						 {
							 set val = "19" _ val
						 }

	    		    }
	    		    else
	    		    {
		    		    set val = dtTm
	    		    }
    		    }
    		    elseif (column [ "DOB")
    		    {
	    		    set dtTm = rs.%Get(column)
	    		    if ($LENGTH(dtTm) >= 8)
	    		    {
	    		    	set val = $E(dtTm, 1, 4) _ "-"_  $E(dtTm, 5, 6) _ "-"_  $E(dtTm, 7, 8)
	    		    }
	    		    else
	    		    {
		    		    set val = dtTm
	    		    }
    		    }


    			if (ind=1)
    			{
    				set innerArr={}.%Set(column,(val))
    			}
    			else
    			{
	    			Do innerArr.%Set(column,(val))
    			}

    		}

    		Do tArr.%Push((innerArr))
    	}


	}
	set ^webService(tableName _ " array size: ") = tArr.%Size()

   set ^webService("GetParentX12 Start") = id _ " / " _ transType _ ": " _ $ZDATETIME($HOROLOG,3, 1)
    Set tArr = []
    #dim rs As %SQL.StatementResult
    set x12Stream = "", tableName = ""

    set tableName = "IHC_ITF_ITFCOMMON_X12." _ $CASE(transType,"270":"EligibilityRequest","271":"EligibilityResponse",
    "276":"ClaimStatusRequest","277":"ClaimStatusResponse",
    "835":"ClaimPayment","277CA":"ClaimAcknowledgement",
    "837I":"Claim","837P":"Claim","837D":"Claim",
    "999":"ImplementationAcknowledgment","277CA":"ClaimAcknowledgement",
    1:"Unknown")


    set sqlStr = "SELECT * FROM " _ tableName _" where ID = '" _ id _ "'" 

	Set rs = ##class(%SQL.Statement).%ExecDirect(,sqlStr)

    set ^webService("GetParentX12 rs") = sqlStr _", SQLCODE: " _ rs.%SQLCODE _ " " _ $ZDATETIME($HOROLOG,3, 1)
	While rs.%Next() {

		set x12Data = ""

				set ^webService("GetParentX12 ID: ") = (rs.%Get("ID")) _", ROWCOUNT: " _ rs.%ROWCOUNT
				set x12Str = rs.%Get("x12Data")
				try 
				{ 
				   set x12Stream = rs.%Get("x12DataStream")
				} catch (er)
				{
					set ^webService("GetParentX12 x12DataStream") = "NO"
				}
				if ( ( x12Str ="" ) &&($CLASSNAME(x12Stream) [ "GlobalCharacter"))
				{

					set x12Data = "X12 is stored as a Stream, X12 Size: " _ ##class(%Stream.Object).%Open(x12Stream).Size
				}
				else
				{
					set x12Data = x12Str
				}

		    set ^webService("GetParentX12 x12Data: ") = x12Data
			Do tArr.%Push({
				"Operation":"GetParentX12",
				"ID": (rs.%Get("ID")),

				"x12Data": (x12Data)			
			})

	}
	set ^webService("GetParentX12") = "End: " _ $ZDATETIME($HOROLOG,3, 1)
	Do ..%SetStatusCode(200)

	return tArr

set ^webService("TransactionFields") = "Start: " _ $ZDATETIME($HOROLOG,3, 1) Set tArr = [] #dim rs As %SQL.StatementResult
Set rs = ##class(%SQL.Statement).%ExecDirect(,"SELECT * FROM IHC_ITF_ITFCOMMON_X12.TransactionFields order by TransactionCode, DisplayOrder, ID")
While rs.%Next() {
Do tArr.%Push({ "Operation":"TransactionFields", "ID": (rs.%Get("ID")), "Key": (rs.%Get("Key")), "Label": (rs.%Get("Label")), "Type": (rs.%Get("Type")), "Detail": (rs.%Get("Detail")), "TransactionCode": (rs.%Get("TransactionCode")), "TransactionName": (rs.%Get("TransactionName")) })
} set ^webService("TransactionFields") = "End: " _ $ZDATETIME($HOROLOG,3, 1) Do ..%SetStatusCode(200)
return tArr

	Set result={}
    set ^webService("SaveDisplayColumns") = "Start: " _ $ZDATETIME($HOROLOG,3, 1)
	If '..GetJSONFromRequest(.obj) {
		Set %response.Status = 400 // ..#HTTP400BADREQUEST
		Set error = {"errormessage": "JSON not found"}
		Write error.%ToJSON()
		Quit $$$OK
	}
	set ^webService("SaveDisplayColumns JSON") = obj.%ToJSON()
	set ^webService("SaveDisplayColumns") = "ValidateJSONForDisplayColumns: " _ $ZDATETIME($HOROLOG,3, 1)
	If '..ValidateJSONForDisplayColumns(obj,.error) {
		Set %response.Status = 400 // ..#HTTP400BADREQUEST
		Write error.%ToJSON()
		Quit $$$OK
	}

	set ^webService("SaveDisplayColumns") = "CopyDisplayColumnsFromJSON " _ $ZDATETIME($HOROLOG,3, 1)
	Do ..CopyDisplayColumnsFromJSON(.obj,.result)

	do result.%Set("Operation","SaveDisplayColumns")


	Quit result

Set error = {}

If obj.%Get("User") = "" {
	set ^webService("ValidateJSONForDisplayColumns") = "User was blank"
	Set error.errormessage = "User was blank"
	Quit 0
}	

set ^webService("ValidateJSONForDisplayColumns") = "ValidateJSONForDisplayColumns: " _ obj.%Get("User")
Quit 1

	set ^webService("CopyDisplayColumnsFromJSON User: ") = obj.User
	set deleteRows = 1

	set iter = obj.displayColumns.%GetIterator()

    while iter.%GetNext(.key , .value ) {
	    if ( (value.TransactionCode '= "") && (value.key '= "" ))
	    {
		  	set cm = ##class(IHC.ITF.ITFCOMMON.X12.DisplayColumns).%New()
			Set cm.User=obj.User
			set cm.TransactionCode = value.TransactionCode
			Set cm.Key = value.key
			set cm.Order = value.Order	
			set cm.Setting = value.Setting
			set cm.Mode = value.Mode
			set cm.LastmodDtTM = $ZDATETIME($HOROLOG,3, 1)
			if (deleteRows = 1)
			{
					Set rs = ##class(%SQL.Statement).%ExecDirect(,"DELETE IHC_ITF_ITFCOMMON_X12.DisplayColumns " _ 
					" where user = '" _ obj.User _ "' AND TransactionCode = '" _value.TransactionCode _ "'" _
					" AND Setting = '" _ value.Setting _"'" _
					" AND Mode = '" _ value.Mode _"'")
					Set deleteRows = 0
			}

			Set sc = cm.%Save()
			do result.%Set("Status",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))
			if ($$$ISOK(sc)) {
				set ^webService("CopyDisplayColumnsFromJSON Added") = cm.%Id()	
				do result.%Set("ID", cm.%Id())
				do result.%Set("User", cm.User)
			}
			else
			{
				set ^webService("CopyDisplayColumnsFromJSON Error") = sc
				QUIT
			}
	    }

    }

Set ok = 1
Try {
	Set obj = ##class(%DynamicObject).%FromJSON(%request.Content)
	set ^webService("GetJSONFromRequest ") = obj
} Catch ex {
	Set ok = 0
}
Quit ok

     set ^webService("GetRelatedTransaction Start") = GroupControlNumber _ ", " _ transType _ ": " _ InterchangeSenderID _ ", " _ InterchangeReceiverID _ ", " _ InterchangeControlNumber _ $ZDATETIME($HOROLOG,3, 1)
    Set tArr = []
    #dim rs As %SQL.StatementResult
    set id1=InterchangeSenderID, id2=InterchangeReceiverID
    set tableNm = ""
    if (transType [ "837") // 837 I,P,D
    {	    
	    set transType = "837"
    }
    elseif (transType [ "270") 
    {
    	set tableNm = "IHC_ITF_ITFCOMMON_X12.EligibilityRequest"
    }

    elseif (transType [ "005010X222") // 837 from 999
    {
	    set id2=InterchangeSenderID, id1=InterchangeReceiverID
	    set transType = "837"
	    set tableNm = "IHC_ITF_ITFCOMMON_X12.Claim"
    }
    elseif (transType [ "005010X279") // 270 from 999
    {
	    set id2=InterchangeSenderID, id1=InterchangeReceiverID
	    set transType = "270"
	    set tableNm = "IHC_ITF_ITFCOMMON_X12.EligibilityRequest"
    }
    elseif (transType [ "005010X221") // 835 from 999
    {
	    set id2=InterchangeSenderID, id1=InterchangeReceiverID
	    set transType = "835"
    }


	set tStatement = ##class(%SQL.Statement).%New()
	SET x12query = 5
	SET x12query(1) = "select distinct cl.InterchangeSenderID, cl.InterchangeReceiverID, cl.InterchangeControlNumber, ack.FileName, ack.x12Data as ST, ack2.x12Data as X999, cl.x12Data as tranX12"
	SET x12query(2) = " from  " _ tableNm _ " cl, IHC_ITF_ITFCOMMON_X12.ImplementationAcknowledgment ack, IHC_ITF_ITFCOMMON_X12.ImplementationAcknowledgment ack2 "
	SET x12query(3) = " where ack.GroupControlNumber = cl.GroupControlNumber AND cl.X12DataParentId is null"
	SET x12query(4) = " and ack.X12DataParentId = ack2.ID and ack.GroupVersion = cl.VersionReleaseIndustryIdenti "
	SET x12query(5) = " and cl.GroupControlNumber = ? and cl.InterchangeSenderID = ? and cl.InterchangeReceiverID = ?"
    set tStatus = tStatement.%Prepare(.x12query)
    if $$$ISERR(tStatus)
    {
	    Do ..%SetStatusCode(200)
	   Do tArr.%Push({
				"Operation":"GetRelatedTransaction",
				"Error": (tStatus)})

    }
    else
    {
	    SET rs=tStatement.%Execute(GroupControlNumber, id1, id2 )

	    set ^webService(tableNm _ " - GetRelatedTransaction rs") = "rs " _rs.%SQLCODE _ ", " _ $ZDATETIME($HOROLOG,3, 1)
		While rs.%Next() {

				set ^webService("GetRelatedTransaction While") = rs.%ROWCOUNT _ ", Next " _ $ZDATETIME($HOROLOG,3, 1)
				Do tArr.%Push({
					"Operation":"GetRelatedTransaction",
					"InterchangeSenderID": (rs.%Get("InterchangeSenderID")),
					"InterchangeReceiverID": (rs.%Get("InterchangeReceiverID")),
					"FileName": (rs.%Get("FileName")),
					"InterchangeControlNumber": (rs.%Get("InterchangeControlNumber")),				
					"x12Data": (rs.%Get("X999")),
					"StX12Data": (rs.%Get("ST")),
					"tranX12": (rs.%Get("tranX12"))			
				})

		}

		Do ..%SetStatusCode(200)
    }
    set ^webService("GetRelatedTransaction") = "End: " _ $ZDATETIME($HOROLOG,3, 1)
	return tArr

 set ^webService("GetRelatedEligBenefit Start") = transType _" = "_ TrnRefId _ "/"_ SubscriberId _ ": " _ InterchangeSenderID _ ", " _ InterchangeReceiverID _ ", " _ InterchangeControlNumber _ $ZDATETIME($HOROLOG,3, 1)
    Set tArr = []
    #dim rs As %SQL.StatementResult
    set tRN1RefId = ""
    set tStatement = ##class(%SQL.Statement).%New()
	SET x12query = 8
	SET x12query(1) = "select req.TrnRefId as ReqTrnId, res.TrnRefId as RespTrnId,"
	SET x12query(2) = "req.SubscriberId as ReqSubscriberId, res.SubscriberId as RespSubscriberId,"
	SET x12query(3) = "req.x12Data as ReqX12, res.x12Data as ResX12, req.FileName as reqFileName, res.FileName as resFileName"

	SET x12query(4) = " from IHC_ITF_ITFCOMMON_X12.EligibilityRequest req, IHC_ITF_ITFCOMMON_X12.EligibilityResponse res where "
	SET x12query(5) = " (req.TrnRefId = res.TrnRefId )"
	if (transType = "270")
	{
		SET x12query(6) = " and req.InterchangeControlNumber = ? and req.InterchangeSenderID = ? and req.InterchangeReceiverID = ?"
		SET x12query(7) = " and req.TrnRefId = ?"


		if ( SubscriberId '= "")
		{
			SET x12query(8) = " and req.SubscriberId = ? AND req.SubscriberId =  res.SubscriberId"
		}


	}
	else
	{
		SET x12query(6) = " and res.InterchangeControlNumber = ? and res.InterchangeSenderID = ? and res.InterchangeReceiverID = ?"
		SET x12query(7) = " and res.TrnRefId = ?"
		if ( SubscriberId '= "")
		{

			SET x12query(8) = " and res.SubscriberId = ? AND req.SubscriberId =  res.SubscriberId"
		}


	}

    set tStatus = tStatement.%Prepare(.x12query)
    if $$$ISERR(tStatus)
    {
	    Do ..%SetStatusCode(200)
	    Do tArr.%Push({
				"Operation":"GetRelatedTransaction",
				"Error": (tStatus)})

    }
    else
    {

	    set ^webService("GetRelatedEligBenefit Val") = SubscriberId _ ", " _ TrnRefId _ ", " _InterchangeControlNumber _ ", " _ InterchangeSenderID _ ", " _ InterchangeReceiverID
	  	if ( SubscriberId '= "")
		{
	    	SET rs=tStatement.%Execute(InterchangeControlNumber, InterchangeSenderID, InterchangeReceiverID, TrnRefId, SubscriberId)
		}
		else
		{
			SET rs=tStatement.%Execute(InterchangeControlNumber, InterchangeSenderID, InterchangeReceiverID, TrnRefId)
		}
	     set ^webService("GetRelatedEligBenefit Execute") = rs.%SQLCODE
		While rs.%Next() {

				set ^webService("GetRelatedEligBenefit") = rs.%Get("ReqX12") _ ", Next " _ $ZDATETIME($HOROLOG,3, 1)
				Do tArr.%Push({
					"Operation":"GetRelated27x",
					"ReqTrnId": (rs.%Get("ReqTrnId")),
					"RespTrnId": (rs.%Get("RespTrnId")),
					"ReqSubscriberId": (rs.%Get("ReqSubscriberId")),
					"RespSubscriberId": (rs.%Get("RespSubscriberId")),
					"ReqX12": (rs.%Get("ReqX12")),
					"ResX12": (rs.%Get("ResX12")),
					"ReqFileName": (rs.%Get("reqFileName")),
					"ResFileName": (rs.%Get("resFileName"))			
				})
				set ^webService("GetRelatedEligBenefit While") = "Pushed" _ ", " _ $ZDATETIME($HOROLOG,3, 1)
				QUIT

		}
		set ^webService("GetRelatedEligBenefit End") = tArr.%Size() _ " at " _ $ZDATETIME($HOROLOG,3, 1)
		Do ..%SetStatusCode(200)
    }
	return tArr

set ^webService("GetRelatedClaimStatus Start") = transType _" = "_ SubscriberId _ "/"_ BhtId _ ": " _ InterchangeSenderID _ ", " _ InterchangeReceiverID _ ", " _ InterchangeControlNumber _ " @"_ $ZDATETIME($HOROLOG,3, 1) Set tArr = [] #dim rs As %SQL.StatementResult
set tStatement = ##class(%SQL.Statement).%New() SET x12query = 8 SET x12query(1) = "select req.TrnRefId as ReqTrnRefId, res.TrnRefId as ResTrnRefId," SET x12query(2) = "req.BhtId as ReqBhtId, res.BhtId as ResBhtId," SET x12query(3) = "req.Subscriber as ReqSubscriber, res.Subscriber as ResSubscriber," SET x12query(4) = "req.x12Data as ReqX12, res.x12Data as ResX12, req.FileName as reqFileName, res.FileName as resFileName" SET x12query(5) = " from IHC_ITF_ITFCOMMON_X12.ClaimStatusRequest req, IHC_ITF_ITFCOMMON_X12.ClaimStatusResponse res where " SET x12query(6) = " (req.TrnRefId = res.TrnRefId) AND (req.BhtId = res.BhtId) AND (req.SubscriberId = res.SubscriberId)" if (transType = "276") {
SET x12query(7) = " and req.SubscriberId = ? AND req.BhtId = ? AND req.TrnRefId = ?" SET x12query(8) = " and req.InterchangeControlNumber = ? and req.InterchangeSenderID = ? and req.InterchangeReceiverID = ?"
} else {
SET x12query(7) = " and res.SubscriberId = ? AND res.BhtId = ? AND req.TrnRefId = ?" SET x12query(8) = " and res.InterchangeControlNumber = ? and res.InterchangeSenderID = ? and res.InterchangeReceiverID = ?"
} set ^webService("GetRelatedClaimStatus SQL") = x12query(8)
set tStatus = tStatement.%Prepare(.x12query) if $$$ISERR(tStatus) { Do ..%SetStatusCode(200) Do tArr.%Push({ "Operation":"GetRelatedTransaction", "Error": (tStatus)})
} else { SET rs=tStatement.%Execute(SubscriberId, BhtId, TrnRefId, InterchangeControlNumber, InterchangeSenderID, InterchangeReceiverID )
set ^webService("GetRelatedClaimStatus rs") = "CODE: " _rs.%SQLCODE _ ", " _ $ZDATETIME($HOROLOG,3, 1) While rs.%Next() {
set ^webService("GetRelatedClaimStatus While") = rs.%ROWCOUNT _ ", Next " _ $ZDATETIME($HOROLOG,3, 1) Do tArr.%Push({ "Operation":"GetRelatedClaimStatus", "ResTrnRefId": (rs.%Get("ResTrnRefId")), "ReqBhtId": (rs.%Get("ReqBhtId")), "ResBhtId": (rs.%Get("ResBhtId")), "ReqSubscriber": (rs.%Get("ReqSubscriber")), "ResSubscriber": (rs.%Get("ResSubscriber")), "ReqX12": (rs.%Get("ReqX12")), "ResX12": (rs.%Get("ResX12")), "ReqFileName": (rs.%Get("reqFileName")), "ResFileName": (rs.%Get("resFileName"))
}) set ^webService("GetRelatedClaimStatus While Push ") = (rs.%Get("ReqSubscriber"))
} set ^webService("GetRelatedClaimStatus") = "End: " _ tArr.%Size() _ " at " _ $ZDATETIME($HOROLOG,3, 1) Do ..%SetStatusCode(200) } return tArr

