   set ^webService("WorkFlowEntries Start") = "ErrorType = '" _ searchStr _"' AND TransactionType = '"_ TransType _"' AND WorkStatus = '" _ErrorType _"', " _dateRange _ " @ " _ $ZDATETIME($HOROLOG,3, 1)
    Set tArr = []
    #dim rs As %SQL.StatementResult
    set dtStr = ""

    Do $SYSTEM.SQL.Util.SetOption("SelectMode",2)

    if ( searchStr '= "")
    {
	    set errStr = ""
	    set transactionStr = ""
	    set statStr = "WorkStatus = '" _ErrorType _"'"

	    if (searchStr '= "All")
	    {
		    set errStr = " AND ErrorType = '" _ searchStr _"'"
	    }
	    if (TransType '= "All")
	    {
	       set transactionStr = " AND TransactionType = '"_ TransType _"'"
	    }
	    if (dateRange '= "")
	    {
		    set dtStr = " AND CreateDtTm " _ dateRange
	    }


	    if (ErrorType = "Assigned")
	    {

	       set statStr = statStr _ " AND WorkStatus ='Assigned' AND WorkUser = '" _userNm _ "'"
        }
        else
        {
	        set statStr = statStr _ " AND WorkStatus ='" _ ErrorType _"'"
        }
	   	Set rs = ##class(%SQL.Statement).%ExecDirect(,"SELECT top 250 * FROM IHC_ITF_ITFCOMMON_X12.WorkFlow where " _ statStr _ errStr _ transactionStr _ dtStr _ "  order by CreateDtTm desc")

    }
    else
    {
		Set rs = ##class(%SQL.Statement).%ExecDirect(,"SELECT top 250 * FROM IHC_ITF_ITFCOMMON_X12.WorkFlow where ErrList is not null and WorkStatus not in ('Resolved','Ignored') order by CreateDtTm desc")
    }
    set ^webService("WorkFlowEntries rs") = "rs " _ $ZDATETIME($HOROLOG,3, 1)
	While rs.%Next() {

			set ^webService("WorkFlowEntries x12Data") = rs.%Get("ID") _ $ZDATETIME($HOROLOG,3, 1)
			Do tArr.%Push({
				"Operation":"WorkFlowEntries",
				"ID": (rs.%Get("ID")),
				"InterchangeReceiverID": (rs.%Get("InterchangeReceiverID")),
