	set obj = ##class(IHC.ITF.ITFCOMMON.X12.WorkFlow).%OpenId(ID,,.sc)
	set ^webService("WorkFlowEntry open1: ") = sc
	if (obj.OrigX12Id > 0)
	{
		set xObj = ##class(EnsLib.EDI.X12.Document).%OpenId(obj.OrigX12Id,,.sc)
		set ^webService("WorkFlowEntry open2: ") = sc
		if ($IsObject(xObj))
