    Set tArr = []

	set ^webService("UpdateWorkFlowEntry Start") = ID	_"," _ status _", " _ userNm_ "@" _  $ZDATETIME($HOROLOG,3, 1)
	set dtTm = $ZDATETIME($HOROLOG,3, 1)
	set sqlStr = "UPDATE IHC_ITF_ITFCOMMON_X12.WorkFlow set WorkStatus = '" _ status _"'"
	if (status [ "Resolve")
	{ 
	  set sqlStr = "UPDATE IHC_ITF_ITFCOMMON_X12.WorkFlow set WorkStatus = 'Resolved', ResolveDtTm = '" _ dtTm _"'"
	}
	if (status = "Assigned")
	{ 
	 set sqlStr = sqlStr _ ", WorkUser = '" _userNm _"'"
	}
	set sqlStr = sqlStr _ ", LastmodDtTM = '" _ dtTm _"',LastmodID = '" _ modUserNm	_ "' where ID = " _ ID
	set ^webService("UpdateWorkFlowEntry SQL") = sqlStr

	#dim rs As %SQL.StatementResult
	Set rs = ##class(%SQL.Statement).%ExecDirect(, sqlStr )
    set cnt = rs.%ROWCOUNT
    set stat = rs.%SQLCODE
    if (status [ "Resend")
	{
	    &SQL(SELECT InterchangeReceiverID,	InterchangeSenderID, TransactionType, LastmodID, x12Data into :recv, :send, :type, :usr, :data from IHC_ITF_ITFCOMMON_X12.WorkFlow where ID = :ID)
	    IF (SQLCODE = 0)
	    {
		    set source = ##class(EnsLib.EDI.X12.Document).ImportFromString(data)
	 		if ( ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
	 		{
			    set rsndDirc = "/itf-share/itf-tmp/" _ $NAMESPACE _ "/RESEND/"
			    if (source.DocType = "")
			    {
			    	set source.DocType="HIPAA_5010:Interchange:Group"
			    }
			    if ('##class(%File).DirectoryExists(rsndDirc))
			    {
				    Do ##class(%File).CreateDirectoryChain(rsndDirc)
			    }
			    set ctrlNum = $ZSTRIP(source.GetValueAt("ISA:InterchangeControlNumber"), "<>WC")
			    set ^webService("UpdateWorkFlowEntry File SQLCODE") = SQLCODE _", data: " _ $L(data) _ ", ctrl: " _ ctrlNum
			    set ^webService("UpdateWorkFlowEntry Direc") = ##class(%File).DirectoryExists(rsndDirc)
			    set flNm = $REPLACE(rsndDirc _ type_"-"_  recv _"-"_	send_"-"  _ ctrlNum_"-"_ usr_"-"_$ZDATETIME($HOROLOG,3, 1) _ "-Resend.dat", " ","")
			    set fl = ##class(%File).%New(flNm)
			    set stat = fl.Open("WN")
			    if (stat)
			    {
				    set ^webService("UpdateWorkFlowEntry Resend file") = flNm _ ": " _ stat
				    Do fl.Write(data)
				    Do fl.Close()

				    &SQL(UPDATE IHC_ITF_ITFCOMMON_X12.WorkFlow set ResendFile = :flNm, Resent = 1 where ID = :ID)

				    set ^webService("UpdateWorkFlowEntry Resend file") = flNm _", " _ SQLCODE
			    }
			    else
			    {
				    set ^webService("UpdateWorkFlowEntry Error") = " Cound not create file: " _ flNm _", status: " _ stat
			    }
	 		}
	    }
	    else
	    {
		    set ^webService("UpdateWorkFlowEntry Resend SQLCODE") = SQLCODE
	    }
	}

	Do tArr.%Push({		
	"ID": (ID),
	"Row Count": (cnt),
	"Status": (stat),
	"SQLCODE": (SQLCODE)
	})
	Do ..%SetStatusCode(200)

	return tArr


    set count = 10, stDtTm = "", endDtTm="",stat="", addSql="",ID=""
    set ^webService("CreateSql") = $ZDATETIME($HOROLOG,3, 1) _", Array count: " _ searchArr.Count()
    for ind=1:1:searchArr.Count()
    {
	   set param = searchArr.GetAt(ind) 
	   if ( param [ "count")
	   {
		   set count = $ZSTRIP($PIECE(param, "::", 2), "<>W")
	   }
	   if ( param [ "ID::")
	   {
		   set ID = $ZSTRIP($PIECE(param, "::", 2), "<>W")
		   set count = 1
		   QUIT
	   }
	   if ( param [ "startDtTm")
	   {
		   set stDtTm = $ZSTRIP($PIECE(param, "::", 2), "<>W")
	   }
	   elseif ( param [ "endDtTm")
	   {
		   set endDtTm = $ZSTRIP($PIECE(param, "::", 2), "<>W")
	   }
	   elseif ( param [ "status")
	   {
		   set stat = $ZSTRIP($PIECE(param, "::", 2), "<>W")
	   }

	   elseif (( param [ "sql") || ( param [ "Sql"))
	   {
		   if (addSql = "")
		   {
		   	set addSql = $ZSTRIP($PIECE(param, "::", 2), "<>W")
		   }
		   else
		   {
			   set addSql = addSql _ " AND "_ $ZSTRIP($PIECE(param, "::", 2), "<>W")
		   }
	   }
    }

    if (table [ "TA1")
    {
	    set sqlStr = "SELECT top 1000 * FROM " _ table _ " WHERE X12DataParentId is null "
    }
    elseif (ID '= "")
	{
		set sqlStr = "SELECT * FROM " _ table _ " WHERE ID = '" _ ID _"'"
	}	
    else
    {
		set sqlStr = "SELECT top 1000 * FROM " _ table _ " WHERE X12DataParentId is not null "
    }


	if (endDtTm '= "")
	{
		set sqlStr = sqlStr _ " AND ProcessDtTm between '" _ stDtTm _"' AND '" _ endDtTm _"'"
	}
	elseif (stDtTm '= "")
	{
		set sqlStr = sqlStr _ " AND ProcessDtTm > '" _ stDtTm _"'"
	}
	if ( (stat '= "") && (stat '= "All") )
	{
		set sqlStr = sqlStr _ " AND Status = '" _ stat _"'"
	}
	if (addSql '= "")
	{
		set sqlStr = sqlStr _ " AND " _addSql
	}
	set ^webService("CreateSql SQL") = sqlStr
	return sqlStr

