Set error = {}

If obj.%Get("User") = "" {
	set ^webService("ValidateJSONForSearchColumns") = "User was blank"
	Set error.errormessage = "User was blank"
	Quit 0
}	

set ^webService("ValidateJSONForSearchColumns") = "ValidateJSONForSearchColumns: " _ obj.%Get("User")
Quit 1

	set ^webService("CopySearchColumnsFromJSON User: ") = obj.User
	set deleteRows = 1

	set iter = obj.SearchColumns.%GetIterator()

    while iter.%GetNext(.key , .value ) {
	    if ( (value.TransactionCode '= "") && (value.key '= "" ))
	    {
		  	set cm = ##class(IHC.ITF.ITFCOMMON.X12.SearchColumns).%New()
			Set cm.User=obj.User
			set cm.TransactionCode = value.TransactionCode
			Set cm.Key = value.key
			set cm.Setting = value.Setting
			set cm.Mode = value.Mode
			set cm.LastmodDtTM = $ZDATETIME($HOROLOG,3, 1)
			if (deleteRows = 1)
			{
					Set rs = ##class(%SQL.Statement).%ExecDirect(,"DELETE IHC_ITF_ITFCOMMON_X12.SearchColumns " _ 
					" where ""User"" = '" _ obj.User _ "' AND TransactionCode = '" _value.TransactionCode _ "'" _
					" AND Setting = '" _ value.Setting _"'" _
					" AND Mode = '" _ value.Mode _"'")
					Set deleteRows = 0
			}

			Set sc = cm.%Save()
			do result.%Set("Status",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))
			if ($$$ISOK(sc)) {
				set ^webService("CopySearchColumnsFromJSON Added") = cm.%Id()	
				do result.%Set("ID", cm.%Id())
				do result.%Set("User", cm.User)
			}
			else
			{
				set ^webService("CopySearchColumnsFromJSON Error") = sc
				QUIT
			}
	    }

    }

